export default function install(app){const title=document.getElementById('app-title'),subtitle=document.getElementById('app-subtitle');app.assert(title&&subtitle,'App title elements are unavailable');const old={titleColor:title.style.color,subtitleDisplay:subtitle.style.display};title.style.color='#007ac2';subtitle.style.display='none';app.onCleanup(()=>{title.style.color=old.titleColor;subtitle.style.display=old.subtitleDisplay});return{installed:true,visibleTitle:title.textContent,subtitleHidden:subtitle.style.display==='none',titleColor:title.style.color};}